<script>
    const pillData = [
        {
            id: "liikunta_ja_kuntoilu",
            title: "Liikunta ja kuntoilu"
        },
        {
            id: "perhe_ja_ihmissuhteet",
            title: "Perhe ja ihmissuhteet"
        },
        {
            id: "ruoka_ja_ravintolat",
            title: "Ruoka ja ravintolat"
        },
        {
            id: "helsinki_ja_uusimaa",
            title: "Helsinki ja Uusimaa"
        },
        {
            id: "politiikka",
            title: "Politiikka"
        },
        {
            id: "suositukset_kulttuurista",
            title: "Suositukset kulttuurista"
        },
        {
            id: "talous_ja_hs_visio",
            title: "Talous ja HS Visio"
        }
    ];

    let subjectsAreInitialized = false;

    function renderSubjectPills() {
        const flexbox_subjects = document.getElementById("flexbox_subjects");
        pillData.forEach(item => {
            const boxContainer = document.createElement("div");
            boxContainer.className = "pill-container";

            boxContainer.innerHTML = `
                <div id="${item.id}" class="pill">
                    <span class="pill-text">${item.title}</span><span class="pill-icon"></span>
                </div>
            `;
            flexbox_subjects.appendChild(boxContainer);
        });
    }

    function setupSubjectListeners() {
        pillData.forEach(pill => {
            const pillElement = document.getElementById(pill.id);

            if (pillElement) {
                pillElement.addEventListener('click', function () {
                    // Toggle active class
                    this.classList.toggle('active');

                    // Update Braze custom attribute
                    const user = brazeBridge.getUser();
                    if (this.classList.contains('active')) {
                        user.addToCustomAttributeArray("hs_selected_interests", pill.id);
                    } else {
                        user.removeFromCustomAttributeArray("hs_selected_interests", pill.id);
                    }

                    // Send the enqueued data to Braze
                    brazeBridge.requestImmediateDataFlush();
                });
            }
        });
    }

    function initializeSubjects() {
        if (subjectsAreInitialized) return; // Prevent duplicate initialization
        renderSubjectPills();
        setupSubjectListeners();
        subjectsAreInitialized = true;
    }

    // Use only the ab.BridgeReady event to initialize
    window.addEventListener("ab.BridgeReady", initializeSubjects);
</script>
</body>
