            gap: 16px;
            align-self: stretch;
            box-shadow: 1px 1px 3px grey,-1px -1px 3px grey;
            justify-content: space-around;
            width: 100%;
        }
        .container {
            padding: 5px 5px 5px 5px;
        }
        .left-image-container {
            display: flex;
            width: 82px;
            height: 92px;
            flex-direction: column;
            justify-content: start;
            align-items: flex-start;
            flex-shrink: 0;
        }
        .left-image {
            width: 100%;
            height: 100%;
            border-radius: 20px;
        }
        .content {
            flex: 2;
            padding-left: 20px;
            position: relative;
        }
        .svg-container {
            position: absolute;
            bottom: 10px;
            right: 10px;
        }
        .svg-container svg {
            cursor: pointer;
        }
        .click_box {
            height: 29px;
            padding: 0px;
            align-items: center;
            gap: 6px;
            flex-shrink: 0;
            justify-content: end;
            display: flex;
        }
        .title_text {
            color: #1A326A;
            font-family: 'Helsingin-title';
            font-size: 18px;
            font-weight: 700;
            line-height: 19.2px; /* 120% */
            letter-spacing: 0px;
            margin: 0; /* Remove default margin */
            text-align: left;
        }
        .body_text {
            line-break: auto;
            color:  #191919;
            font-family: 'Helsingin';
            font-size: 16px;
            font-style: normal;
            font-weight: 400;
            line-height: 19.2px;
            letter-spacing: 0px;
            margin-top: 4px; /* Reduce space between title and body text */
            text-align: left;
        }
        .text_box {
            align-self: right;
            width: 100%;
            height: 90px;
        }
        .click_icon {
            height: 24px;
            width: 24px;
        }
        .switch {
        position: relative;
        display: inline-block;
        width: 50px;
        height: 20px;
        }

        .switch input { 
        opacity: 0;
        width: 0;
        height: 0;
        }

        .slider {
        position: absolute;
        cursor: pointer;
        top: 0;
        left: 0;
        right: 0;
        bottom: 0;
        background-color: #F7F7F3;
        -webkit-transition: .4s;
        transition: .4s;
        }

        .slider:before {
        position: absolute;
        content: "";
        height: 24px;
        width: 24px;
        left: -2px;
        bottom: -4px;
        background-color: white;
        -webkit-transition: .4s;
        transition: .4s;
        }

        input:checked + .slider {
        background-color: #047651;
        }

        input:focus + .slider {
        box-shadow: 0 0 1px #047651;
        }

        input:checked + .slider:before {
        -webkit-transform: translateX(26px);
        -ms-transform: translateX(26px);
        transform: translateX(26px);
        }

        /* Rounded sliders */
        .slider.round {
        border-radius: 34px;
        border: 1px solid #191919;
        }

        .slider.round:before {
        border-radius: 50%;
        border: 1px solid #191919;
        }

        #flexbox_newsletters {
            padding:10px 10px;
            display: flex;
            flex-wrap: wrap;
            max-width: 800px;
            gap: 10px;
            justify-content: flex-start;
        }

        #flexbox_newsletters > div {
            flex: 1 1 auto;
            max-width: 300px;
        }
        @media screen and (max-width: 700px) {
            #flexbox_newsletters {
                justify-content: center;

            }
        }
