<script>
    // Newsletter data mapping
    const newsletterData = [
        {
            id: "reboot_newsletter_toggle",
            subscriptionGroupId: "5e5165ab-399b-40c3-9a73-a9d9bf29f9d6",
            image: "https://cdn.braze.eu/appboy/communication/assets/svg_assets/files/67e402d04f62230085438a5c/original.svg",
            title: "Energisempi minä",
            description: "Uutiskirjekurssi tuo energiaa ja liikunnan osaksi arkea."
        },
        {
            id: "sport_digi_newsletter_toggle",
            subscriptionGroupId: "594b560b-492b-464c-bc21-22dfd3f5f754",
            image: "https://cdn.braze.eu/appboy/communication/assets/svg_assets/files/67e402d8f1bda50073fb6bf5/original.svg",
            title: "Sport Digi",
            description: "Sport Digi tarjoaa viikoittain hyvinvointia, treeniä ja inspiraatiota."
        },
        {
            id: "visio_newsletter_toggle",
            subscriptionGroupId: "656e5f88-6462-4ce7-835d-0feb3e7fbe26",
            image: "https://cdn.braze.eu/appboy/communication/assets/svg_assets/files/67e402d885d29f00757d85ca/original.svg",
            title: "Visio",
            description: "Seuraa talouden trendejä, yritysuutisia ja analyyseja."
        },
        {
            id: "hyviauutisia_newsletter_toggle",
            subscriptionGroupId: "fa47e135-899f-4484-9842-5c9282883453",
            image: "https://cdn.braze.eu/appboy/communication/assets/svg_assets/files/68273dbdbab66c009440d23d/original.svg",
            title: "Hyviä uutisia",
            description: "Kerää yhteen arkeasi piristävät uutiset kotimaasta ja maailmalta."
        },
        {
            id: "ruoka_newsletter_toggle",
            subscriptionGroupId: "01e8dccc-73d0-491a-8e9e-b071844dd215",
            image: "https://cdn.braze.eu/appboy/communication/assets/svg_assets/files/67e402d8cd1eef00836f03a1/original.svg",
            title: "Ruoka & Viini",
            description: "Viikon parhaat reseptit, ravintolauutiset ja viinisuositukset."
        }
    ];

    // Function to render newsletters dynamically
    function renderNewsletters() {
        const flexbox_newsletters = document.getElementById("flexbox_newsletters");
        newsletterData.forEach(newsletter => {
            const boxContainer = document.createElement("div");
            boxContainer.className = "box-container";

            boxContainer.innerHTML = `
                <div class="left-image-container">
                    <div class="left-image">
                        <img class="left-image" src="${newsletter.image}" alt="${newsletter.title}">
                    </div>
                </div>
                <div>
                    <div class="text_box">
                        <h2 class="title_text">${newsletter.title}</h2>
                        <p class="body_text">${newsletter.description}</p>
                    </div>
                    <div class="click_box">
                        <label class="switch">
                            <input id="${newsletter.id}" type="checkbox" unchecked>
                            <span class="slider round"></span>
                        </label>
                    </div>
                </div>
            `;
            flexbox_newsletters.appendChild(boxContainer);
        });
    }

    // Function to add event listeners for each toggle
    function setupNewsletterListeners() {
        newsletterData.forEach(newsletter => {
            const toggleElementNewsletter = document.getElementById(newsletter.id);

            if (toggleElementNewsletter) {
                toggleElementNewsletter.addEventListener('change', function () {
                    if (this.checked) {
                        brazeBridge.getUser().addToSubscriptionGroup(newsletter.subscriptionGroupId);
                    } else {
                        brazeBridge.getUser().removeFromSubscriptionGroup(newsletter.subscriptionGroupId);
                    }
                    // Send the enqueued data to Braze
                    brazeBridge.requestImmediateDataFlush();
                });
            }
        });
    }

    let newslettersAreInitialized = false;

    function initializeNewsletters() {
        if (newslettersAreInitialized) return;
        renderNewsletters();
        setupNewsletterListeners();
        newslettersAreInitialized = true;
    }

    window.addEventListener("ab.BridgeReady", initializeNewsletters);
</script>
</body>
